import {serviceShadow} from './approved-service-host.js';
import {THRESHOLDS} from './account-score.js';
import {STATUE_FAMILY} from './statue-family-manifest.js';
import {HUD_ART} from './hud-art-registry.js';
const fmt=n=>n.toLocaleString('pt-BR');
export function statuePresentation(view){
 if(!view||!Number.isSafeInteger(view.total)||!Number.isFinite(view.fill)||!STATUE_FAMILY[view.tier])return null;
 return {total:view.total,tier:view.tier,stage:view.stage,fill:Math.max(0,Math.min(1,view.fill)),name:STATUE_FAMILY[view.tier].name,portrait:STATUE_FAMILY[view.tier].file,nextName:STATUE_FAMILY[view.tier+1]?.name??null,remaining:view.next===null?0:Math.max(0,view.next-view.total),max:view.next===null};
}
function shell(doc){if(doc.querySelector('link[data-approved-statue-shell]'))return;const link=doc.createElement('link');link.rel='stylesheet';link.href='approved-statue-shell.css';link.dataset.approvedStatueShell='';doc.head.append(link);}
export function mountApprovedStatue(dialog,view,{onClose=()=>{}}={}){
 const doc=dialog.ownerDocument; shell(doc);
 const shadow=serviceShadow(dialog,"<div id=\"gv-statue-service\">\n<div class=\"stage\"><section class=\"window\" id=\"st-window\" aria-labelledby=\"st-title\"><header class=\"head\"><img id=\"st-icon\" alt=\"\"><h2 id=\"st-title\">Pontuação</h2><button type=\"button\" class=\"close cursor-interaction\" id=\"st-close\" aria-label=\"Fechar\">×</button></header><div class=\"main\"><div class=\"overview\" id=\"st-overview\"><img class=\"portrait\" id=\"st-portrait\" alt=\"\"><div class=\"info\"><p class=\"elo\" id=\"st-elo\"></p><p class=\"total\"><strong id=\"st-total\"></strong><small>pts</small></p><div class=\"track\" id=\"st-progress\" role=\"progressbar\" aria-label=\"Progresso do elo atual\" aria-valuemin=\"0\" aria-valuemax=\"100\"><i id=\"st-fill\"></i></div><p class=\"next\" id=\"st-next\"></p></div></div><section class=\"milestones\" id=\"st-milestones\" hidden aria-labelledby=\"st-milestones-title\"><h3 id=\"st-milestones-title\">Marcos</h3><ol id=\"st-rows\"></ol></section><div class=\"unavailable\" id=\"st-unavailable\" hidden><h3>Pontuação indisponível</h3><p>Seu progresso foi preservado.</p></div></div><footer class=\"footer\"><button type=\"button\" class=\"button cursor-interaction\" id=\"st-toggle\" aria-expanded=\"false\" aria-controls=\"st-milestones\">Ver marcos</button><p class=\"caption\">Pontuação acumulada nas expedições</p></footer></section><div class=\"handoff\" id=\"st-handoff\" hidden></div><span class=\"live\" id=\"st-live\" aria-live=\"polite\"></span></div>\n</div>"),style=doc.createElement('link');style.rel='stylesheet';style.href='approved-statue-ui.css';shadow.prepend(style);
 const root=shadow.querySelector('#gv-statue-service'),$=id=>root.querySelector('#'+id),v=statuePresentation(view),oldWidth=dialog.style.getPropertyValue('width'),priority=dialog.style.getPropertyPriority('width');
 dialog.style.setProperty('width','min(760px, calc(100vw - 24px))','important');root.dataset.soft=String(doc.body.classList.contains('soft-fx'));let milestones=false;
 $('st-handoff').remove();$('st-icon').src=HUD_ART.record.url;$('st-close').onclick=onClose;
 function render(){const show=!!v&&milestones;$('st-overview').hidden=!v||show;$('st-milestones').hidden=!show;$('st-unavailable').hidden=!!v;$('st-toggle').disabled=!v;$('st-toggle').textContent=show?'Voltar':'Ver marcos';$('st-toggle').setAttribute('aria-expanded',String(show));}
 if(v){$('st-overview').dataset.max=String(v.max);$('st-portrait').src=v.portrait;$('st-portrait').alt='Estátua · Elo '+v.stage+' · '+v.name;$('st-elo').innerHTML='<strong>'+v.name+'</strong> Elo '+v.stage+' / '+THRESHOLDS.length;$('st-total').textContent=fmt(v.total);$('st-fill').style.width=v.fill*100+'%';$('st-progress').setAttribute('aria-valuenow',String(Math.round(v.fill*100)));$('st-progress').setAttribute('aria-valuetext',v.max?'Último elo':fmt(v.remaining)+' pontos para '+v.nextName);$('st-next').innerHTML=v.max?'<span class="max-label">Elo máximo</span>':'Faltam <strong>'+fmt(v.remaining)+' pts</strong><br>para '+v.nextName;$('st-rows').innerHTML=THRESHOLDS.map((n,i)=>'<li data-status="'+(i<v.tier?'done':i===v.tier?'current':'future')+'" '+(i===v.tier?'aria-current="step"':'')+'><span class="step" aria-label="'+(i<=v.tier?'Conquistado':'Elo '+(i+1))+'">'+(i<v.tier?'✓':i+1)+'</span><span>'+STATUE_FAMILY[i].name+'</span><b>'+fmt(n)+'</b></li>').join('');}
 $('st-toggle').onclick=()=>{milestones=!milestones;render();$('st-live').textContent=milestones?'Sete marcos de pontuação.':'Pontuação atual.';};render();$('st-close').focus({preventScroll:true});
 return ()=>{if(oldWidth)dialog.style.setProperty('width',oldWidth,priority);else dialog.style.removeProperty('width');};
}
